<?php
require __DIR__.'/bootstrap.php';require_perm('income.manage');$me=user();
$branch=is_admin()?null:require_branch();$where=$branch===null?'':' WHERE i.branch_id='.(int)$branch;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
if(isset($_POST['delete'])){$id=(int)$_POST['id'];$pdo->beginTransaction();try{$pdo->prepare("DELETE FROM bank_transactions WHERE source_table='income_entries' AND source_id=?")->execute([$id]);$d=$pdo->prepare('DELETE FROM income_entries WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch));$d->execute([$id]);$pdo->commit();flash('success','Income entry deleted.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Income entry could not be deleted.');}redirect('income.php');}
if(isset($_POST['update'])){$id=(int)$_POST['id'];$bankId=(int)($_POST['bank_account_id']??0);if($bankId){$eb=$pdo->prepare('SELECT branch_id FROM income_entries WHERE id=?');$eb->execute([$id]);if(!bank_account_id_for_branch($bankId,(int)$eb->fetchColumn())){flash('danger','Select an active bank account for this branch.');redirect('income.php');}}$u=$pdo->prepare('UPDATE income_entries SET income_date=?,category=?,amount=?,shipment_id=?,payer=?,payment_method=?,reference_no=?,description=?,bank_account_id=? WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch));$u->execute([$_POST['income_date'],$_POST['category'],$_POST['amount'],$_POST['shipment_id']?:null,trim($_POST['payer']),$_POST['payment_method'],trim($_POST['reference_no']),trim($_POST['description']),$bankId?:null,$id]);sync_income_bank_transaction($id,$bankId,(float)$_POST['amount'],$_POST['income_date']);flash('success','Income entry updated.');redirect('income.php');}
$incomeBranch=$branch??(int)$_POST['branch_id'];$bankId=(int)($_POST['bank_account_id']??0);if($bankId&&!bank_account_id_for_branch($bankId,$incomeBranch)){flash('danger','Select an active bank account for this branch.');redirect('income.php');}try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO income_entries(income_date,category,amount,shipment_id,bank_account_id,branch_id,payer,payment_method,reference_no,description,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$_POST['income_date'],$_POST['category'],$_POST['amount'],$_POST['shipment_id']?:null,$bankId?:null,$incomeBranch,trim($_POST['payer']),$_POST['payment_method'],trim($_POST['reference_no']),trim($_POST['description']),$me['id']]);$eid=(int)$pdo->lastInsertId();if($bankId)add_bank_transaction($bankId,'Income','income_entries',$eid,(float)$_POST['amount'],$_POST['income_date'].' '.date('H:i:s'));$pdo->commit();flash('success','Income entry recorded.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Income entry could not be recorded.');}redirect('income.php');}
$manual=$pdo->query('SELECT i.*,s.awb,b.name bank_account_name FROM income_entries i LEFT JOIN shipments s ON s.id=i.shipment_id LEFT JOIN bank_accounts b ON b.id=i.bank_account_id'.$where.' ORDER BY i.income_date DESC,i.id DESC')->fetchAll();$banks=$pdo->query('SELECT id,name,bank_name,account_number,branch_id FROM bank_accounts WHERE active=1'.($branch===null?'':' AND branch_id='.(int)$branch).' ORDER BY name')->fetchAll();
$paymentWhere=$branch===null?'':' WHERE s.branch_id='.(int)$branch;
$payments=$pdo->query('SELECT p.id,DATE(p.paid_at) income_date,p.amount,p.payment_method,p.reference_no,p.location,s.awb,s.id shipment_id FROM payments p JOIN shipments s ON s.id=p.shipment_id'.$paymentWhere.' ORDER BY p.paid_at DESC')->fetchAll();
$monthPayments=(float)$pdo->query("SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN shipments s ON s.id=p.shipment_id".($branch===null?" WHERE p.paid_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')":" WHERE s.branch_id=".(int)$branch." AND p.paid_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')"))->fetchColumn();
$monthManual=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM income_entries".($branch===null?" WHERE income_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')":" WHERE branch_id=".(int)$branch." AND income_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')"))->fetchColumn();
$shipments=$pdo->query("SELECT id,awb FROM shipments WHERE status<>'Cancelled'".($branch===null?'':' AND branch_id='.(int)$branch).' ORDER BY shipment_date DESC')->fetchAll();$title='Income';require __DIR__.'/partials/header.php';
?>
