n" required></div><div class="modal-footer"><button class="btn btn-primary" name="update">Save changes</button></div></form></div></div>
<script>
(function(){
  const parse=(el)=>{try{return JSON.parse(el.dataset.income||'{}')}catch(e){return{}}};
  document.querySelectorAll('[data-bs-target="#incomeEdit"]').forEach(b=>b.addEventListener('click',()=>{
    const d=parse(b),f=document.querySelector('#incomeEditForm');
    const set=(n,v)=>{const el=f.querySelector('[name="'+n+'"]');if(el)el.value=(v===null||v===undefined)?'':v;};
    f.querySelector('[name="id"]').value=d.id||'';
    set('income_date',d.income_date);set('category',d.category);set('amount',d.amount);
    set('shipment_id',d.shipment_id||'');set('bank_account_id',d.bank_account_id||'');set('payer',d.payer);set('payment_method',d.payment_method);
    set('reference_no',d.reference_no);set('description',d.description);
  }));
  document.querySelectorAll('[data-bs-target="#incomeView"]').forEach(b=>b.addEventListener('click',()=>{
    const d=parse(b),box=document.querySelector('#incomeViewBody');
    const row=(k,v)=>{const x=v===null||v===''?'—':v;return '<div class="d-flex justify-content-between mb-1"><span class="text-secondary">'+k+'</span><strong>'+x+'</strong></div>';};
    let h='<div class="mb-2"><span class="badge text-bg-primary">#'+(d.id||'')+'</span>'+(d.awb?' <span class="badge text-bg-light border">AWB: '+d.awb+'</span>':'')+'</div>';
    h+=row('Date',d.income_date)+row('Category',d.category)+row('Amount',d.amount)+row('Bank account',d.bank_account_name||d.bank_account_id||'—')+row('Payer',d.payer)+row('Payment method',d.payment_method)+row('Reference',d.reference_no)+row('Description',d.description);
    box.innerHTML=h;
  }));
})();
</script>
